from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
marker='''\n        /* CONTENT-PANELS-OPAQUE-2026-09-03 */\n        body::before {\n            opacity: .18 !important;\n        }\n\n        .site-content,\n        section:not(.hero),\n        .features,\n        .story-section,\n        .terms-highlights,\n        .faq-section {\n            background-color: rgba(247,252,244,.34) !important;\n            backdrop-filter: none !important;\n        }\n\n        .shop-layout,\n        .product-card,\n        .feature-card,\n        .terms-card,\n        .faq-item,\n        .story-copy,\n        .process-step,\n        .product-details-window.product-details-banner {\n            background: #ffffff !important;\n            opacity: 1 !important;\n            backdrop-filter: none !important;\n        }\n\n        .shop-layout,\n        .feature-card,\n        .terms-card,\n        .faq-item,\n        .story-copy,\n        .process-step {\n            box-shadow: 0 18px 44px rgba(18,53,36,.12);\n            border-color: rgba(18,53,36,.10) !important;\n        }\n\n        .product-card {\n            box-shadow: 0 20px 50px rgba(18,53,36,.16) !important;\n        }\n\n        @media (max-width: 820px) {\n            body::before { opacity: .14 !important; }\n            .site-content,\n            section:not(.hero),\n            .features,\n            .story-section,\n            .terms-highlights,\n            .faq-section { background-color: rgba(247,252,244,.40) !important; }\n        }\n'''
if 'CONTENT-PANELS-OPAQUE-2026-09-03' not in s:
    s=s.replace('</style>', marker+'\n</style>',1)
p.write_text(s,encoding='utf-8')
